def _hex_to_rgb(hex_color: str) -> tuple[int, int, int] | None:
    """Convert a '#rrggbb' hex color string to an rgb tuple."""
    try:
        rgb = rgb_hex_to_rgb_list(hex_color.lstrip("#"))
    except ValueError:
        return None
    if len(rgb) != 3:
        return None
    return (rgb[0], rgb[1], rgb[2])


async def async_setup_entry(
    hass: HomeAssistant,
    entry: SmConfigEntry,
    async_add_entities: AddConfigEntryEntitiesCallback,
) -> None:
    """Set up the SMLIGHT ambilight from a config entry."""
    coordinator = entry.runtime_data.data

    if coordinator.data.info.has_peripherals:
        async_add_entities([SmLightEntity(coordinator)])


class SmLightEntity(SmEntity, LightEntity):
    """Representation of the SMLIGHT Ultima ambilight LED strip."""

    coordinator: SmDataUpdateCoordinator

    translation_key = "ambilight"
    icon = "mdi:led-strip"
    _attr_entity_category = None
    _attr_supported_color_modes = {ColorMode.RGB}
    _attr_color_mode = ColorMode.RGB
    _attr_supported_features = LightEntityFeature.EFFECT
    _attr_effect_list = AMBI_EFFECT_LIST

    def __init__(self, coordinator: SmDataUpdateCoordinator) -> None:
        """Initialize the ambilight entity."""
        super().__init__(coordinator)
        self._attr_unique_id = f"{coordinator.unique_id}-ambilight"

    async def async_added_to_hass(self) -> None:
        """Run when entity about to be added to hass."""
        await super().async_added_to_hass()
        self.async_on_remove(
            self.coordinator.client.sse.register_page_cb(
                Pages.API2_PAGE_AMBILIGHT, self.coordinator.update_ambilight
            )
        )

    @property
    def _ambilight(self) -> AmbilightPayload | None:
        """Return the current ambilight state."""
        return self.coordinator.data.sensors.ambilight

    @property
    def is_on(self) -> bool:
        """Return true if the light is on."""
        ambilight = self._ambilight
        if ambilight is None or ambilight.ultLedMode is None:
            return False
        return ambilight.ultLedMode != AmbiEffect.WSULT_OFF

    @property
    def brightness(self) -> int | None:
        """Return the brightness of the light."""
        ambilight = self._ambilight
        if ambilight is None:
            return None
        return ambilight.ultLedBri

    @property
    def rgb_color(self) -> tuple[int, int, int] | None:
        """Return the rgb color value."""
        ambilight = self._ambilight
        if ambilight is None or ambilight.ultLedColor is None:
            return None
        return _hex_to_rgb(ambilight.ultLedColor)

    @property
    def effect(self) -> str | None:
        """Return the current effect."""
        ambilight = self._ambilight
        if ambilight is None or ambilight.ultLedMode is None:
            return None
        mode = int(ambilight.ultLedMode)
        if mode == AmbiEffect.WSULT_OFF:
            return None
        if 0 <= mode < len(AMBI_EFFECT_LIST):
            return AMBI_EFFECT_LIST[mode]
        return None

    async def _async_set_ambilight(self, payload: AmbilightPayload) -> None:
        """Send an ambilight command, converting connection errors."""
        try:
            await self.coordinator.client.actions.ambilight(payload)
        except SmlightConnectionError as err:
            raise HomeAssistantError(
                translation_domain=DOMAIN,
                translation_key="cannot_connect_device",
                translation_placeholders={"error": str(err)},
            ) from err

    async def async_turn_on(self, **kwargs: Any) -> None:
        """Turn the ambilight on."""
        payload = AmbilightPayload()

        if ATTR_EFFECT in kwargs:
            effect = kwargs[ATTR_EFFECT]
            if effect not in AMBI_EFFECT_LIST:
                return
            payload.ultLedMode = AmbiEffect(AMBI_EFFECT_LIST.index(effect))
        elif not self.is_on:
            payload.ultLedMode = AmbiEffect.WSULT_SOLID

        if ATTR_BRIGHTNESS in kwargs:
            payload.ultLedBri = kwargs[ATTR_BRIGHTNESS]

        if ATTR_RGB_COLOR in kwargs:
            payload.ultLedMode = AmbiEffect.WSULT_SOLID
            payload.ultLedColor = f"#{color_rgb_to_hex(*kwargs[ATTR_RGB_COLOR])}"

        if payload == AmbilightPayload():
            return

        await self._async_set_ambilight(payload)

    async def async_turn_off(self, **kwargs: Any) -> None:
        """Turn the ambilight off."""
        await self._async_set_ambilight(
            AmbilightPayload(ultLedMode=AmbiEffect.WSULT_OFF)
        )
